lessons.solution:
def expense_total(amounts):
    if any(amount < 0 for amount in amounts):
        raise ValueError("Expense amounts must be non-negative")
    return sum(amounts)

print(expense_total([10,20,5]))

lessons.tests:
assert expense_total([])==0
assert expense_total([10,20,5])==35
try:
    expense_total([10,-1])
except ValueError:
    pass
else:
    raise AssertionError("Negative amounts must raise ValueError")

